Amend the existing `node:fs` import to also import `mkdirSync` and `symlinkSync`, then add this test inside the existing `describe("doctor-contract", ...)` block:

```ts
test("non-regular corpus entries fail by named findings instead of a loader exception", () => {
  const doc = frozen();
  const matrix = frozenMatrix();
  const report = fixtureOf("complete");
  const directory = mkdtempSync(join(tmpdir(), "aos-doctor-nonregular-corpus-"));

  try {
    for (const [name, text] of Object.entries(fixtureText)) {
      writeFileSync(join(directory, name), text);
    }

    mkdirSync(join(directory, "unexpected-directory"));
    symlinkSync(
      join(directory, "missing-target.json"),
      join(directory, "unexpected-link"),
      "file"
    );

    let result!: ReturnType<typeof validate>;
    assert.doesNotThrow(() => {
      result = validate(report, doc, matrix, corpusOf(readCorpusText(directory)));
    });

    assert.deepEqual(result.errors, [
      "CONTRACT_CANONICAL_FIXTURE_UNDECLARED unexpected-directory is not declared by the doctor contract",
      "CONTRACT_CANONICAL_FIXTURE_UNDECLARED unexpected-link is not declared by the doctor contract"
    ]);
    assert.equal(result.ok, false);
    assert.equal(result.verdict, "SCORE_BLOCKED");
    assert.equal(result.exit_code, 30);
    assert.deepEqual(result.reasons, []);
    assert.deepEqual(result.human_projection, []);
  } finally {
    rmSync(directory, { recursive: true, force: true });
  }
});
```
